import unittest
from solution import merge_windows

class VisibleTests(unittest.TestCase):
    def test_overlapping_windows(self):
        self.assertEqual(merge_windows([(1, 4), (2, 6)]), [(1, 6)])

    def test_touching_windows_stay_separate(self):
        self.assertEqual(merge_windows([(1, 3), (3, 5)]), [(1, 3), (3, 5)])

    def test_nested_windows(self):
        self.assertEqual(merge_windows([(1, 9), (2, 3), (4, 6)]), [(1, 9)])

