import unittest
from solution import merge_windows

class HiddenTests(unittest.TestCase):
    def test_empty_windows_ignored(self):
        self.assertEqual(merge_windows([]), [])
        self.assertEqual(merge_windows([(1, 1), (2, 2)]), [])
        self.assertEqual(merge_windows([(1, 3), (3, 3), (3, 5)]), [(1, 3), (3, 5)])

    def test_sorting_duplicates_and_no_mutation(self):
        windows = [(8, 10), (2, 5), (2, 5), (4, 9)]
        self.assertEqual(merge_windows(windows), [(2, 10)])
        self.assertEqual(windows, [(8, 10), (2, 5), (2, 5), (4, 9)])

    def test_negative_endpoints_and_overlap_bridge(self):
        self.assertEqual(merge_windows([(-5, -2), (-2, 0), (-3, -1), (0, 4)]), [(-5, 0), (0, 4)])

    def test_reversed_interval(self):
        with self.assertRaises(ValueError):
            merge_windows([(8, 3)])
